type IdempotencyKey = string & { readonly __brand: 'IdempotencyKey' };
interface IdempotencyStore {
  claim(key: IdempotencyKey, ttlMs: number): Promise<boolean>;
}

async function consume(msg: Message, store: IdempotencyStore, h: Handler) {
  const first = await store.claim(msg.key, REDELIVERY_WINDOW_MS);
  if (!first) return ack(msg);                 // duplicate: absorb
  await h.applyEffects(msg);                   // exactly-once effects
  await ack(msg);
}
